`;

const Features = styled.div`
  margin-top: 2rem;
  padding: 2rem;
  background: white;
  border-radius: 20px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
`;

const FeaturesTitle = styled.h3`
  font-size: 1.5rem;
  margin-bottom: 1rem;
  color: #333;
`;

const FeaturesList = styled.ul`
  list-style: none;
  padding: 0;
  margin: 0;
`;

const FeatureItem = styled.li`
  padding: 0.5rem 0;
  color: #666;
  display: flex;
  align-items: center;
  gap: 0.5rem;

  &::before {
    content: '✓';
    color: #4caf50;
    font-weight: bold;
  }
`;

const NotFound = styled.div`
  text-align: center;
  padding: 4rem 2rem;
`;

const ProductDetail = () => {
  const { id } = useParams();
  const { state, addToCart } = useApp();
  const navigate = useNavigate();
  const [quantity, setQuantity] = useState(1);
  const [isWishlisted, setIsWishlisted] = useState(false);

  const product = state.products.find(p => p.id === id);

  useEffect(() => {
    if (!state.loading && state.products.length > 0 && !product) {
      navigate('/products');
    }
  }, [product, state.loading, state.products.length, navigate]);

  if (state.loading) {
    return (
      <DetailContainer>
        <div className="spinner"></div>
      </DetailContainer>
    );
  }

  if (!product) {
    return (
      <DetailContainer>
        <DetailContent>
          <NotFound>
            <h2>Product not found</h2>
            <p>The product you're looking for doesn't exist.</p>
            <Link to="/products" className="btn btn-primary">
              Back to Products
            </Link>
          </NotFound>
        </DetailContent>
      </DetailContainer>
    );
  }

  const handleAddToCart = () => {
    for (let i = 0; i < quantity; i++) {
      addToCart(product);
    }
    setQuantity(1);
  };

  const handleQuantityChange = (change) => {
    const newQuantity = quantity + change;
    if (newQuantity >= 1 && newQuantity <= 10) {
      setQuantity(newQuantity);
    }
  };

  const toggleWishlist = () => {
    setIsWishlisted(!isWishlisted);
  };

  const renderStars = (rating) => {
    return Array.from({ length: 5 }, (_, i) => (
      <FiStar key={i} fill={i < Math.floor(rating) ? '#ffc107' : 'none'} />
    ));
  };

  const getProductEmoji = (category) => {
    const emojis = {
      'Face': '💄',
      'Eyes': '👁️',
      'Lips': '💋',
      'Nails': '💅'
    };
    return emojis[category] || '💄';
  };

  const features = [
    'Premium quality ingredients',
    'Long-lasting formula',
    'Dermatologist tested',
    'Cruelty-free',
    'Suitable for all skin types'
  ];

  return (
    <DetailContainer>
      <DetailContent>
        <BackLink to="/products">
          <FiArrowLeft />
          Back to Products
        </BackLink>

        <ProductGrid>
          <ImageSection>
            <MainImage>
              {getProductEmoji(product.category)}
            </MainImage>
          </ImageSection>

          <ProductInfo>
            <CategoryBadge>{product.category}</CategoryBadge>

            <div>
              <ProductTitle>{product.name}</ProductTitle>
              <BrandName>{product.brand}</BrandName>
            </div>

            <RatingSection>
              <StarRating>
                {renderStars(product.rating)}
              </StarRating>
              <ReviewCount>({product.reviews} reviews)</ReviewCount>
            </RatingSection>

            <PriceSection>
              <Price>${product.price}</Price>
              <StockStatus inStock={product.inStock}>
                {product.inStock ? 'In Stock' : 'Out of Stock'}
              </StockStatus>
            </PriceSection>

            <Description>{product.description}</Description>

            <QuantitySection>
              <QuantityLabel>Quantity:</QuantityLabel>
              <QuantityControls>
                <QuantityButton
                  onClick={() => handleQuantityChange(-1)}
                  disabled={quantity <= 1}
                >
                  <FiMinus />
                </QuantityButton>
                <QuantityDisplay>{quantity}</QuantityDisplay>
                <QuantityButton
                  onClick={() => handleQuantityChange(1)}
                  disabled={quantity >= 10}
                >
                  <FiPlus />
                </QuantityButton>
              </QuantityControls>
            </QuantitySection>

            <ActionButtons>
              <AddToCartButton
                onClick={handleAddToCart}
                disabled={!product.inStock}
              >
                <FiShoppingBag />
                {product.inStock ? 'Add to Cart' : 'Out of Stock'}
              </AddToCartButton>

              <WishlistButton onClick={toggleWishlist}>
                <FiHeart fill={isWishlisted ? '#e91e63' : 'none'} />
              </WishlistButton>
            </ActionButtons>
          </ProductInfo>
        </ProductGrid>

        <Features>
          <FeaturesTitle>Product Features</FeaturesTitle>
          <FeaturesList>
            {features.map((feature, index) => (
              <FeatureItem key={index}>{feature}</FeatureItem>
            ))}
          </FeaturesList>
        </Features>
      </DetailContent>
    </DetailContainer>
  );
};

export default ProductDetail;
